:root { font-family: system-ui, sans-serif; color: #182537; background: #f5f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2ea; border-radius: 12px; }
h1 { margin-top: 0; font-size: 2rem; overflow-wrap: anywhere; }
form { display: grid; grid-template-columns: 1fr auto; gap: 12px; }
.project-rename { margin-bottom: 28px; }
.search-form { margin-top: 20px; }
.project-import { margin-top: 28px; grid-template-columns: 1fr; }
label { grid-column: 1 / -1; font-weight: 600; }
input, button, select, textarea { font: inherit; padding: 10px 14px; border-radius: 6px; }
input, textarea { min-width: 0; border: 1px solid #8d9aab; }
textarea { resize: vertical; }
button { border: 1px solid #214cc4; color: white; background: #214cc4; cursor: pointer; }
